(() => {
  const MARKET=window.SmartRiskEcuadorMarket;
  if(!MARKET) return;
  const STORAGE='smartrisk_consultoria_market_eval_v1';
  const criteria=[
    ['fit','Ajuste estratégico','Encaje con microzonificación y servicios de riesgo.',10],
    ['need','Necesidad técnica','Necesidad territorial/riesgo que justifique el servicio.',15],
    ['market','Escala / potencial','Dimensión y potencial económico del alcance.',10],
    ['budget','Capacidad / señal presupuestaria','Probabilidad real de contar con presupuesto o financiamiento.',15],
    ['contact','Acceso institucional','Calidad del contacto y acceso a decisores/técnicos.',10],
    ['timing','Ventana de contratación','Madurez y momento probable del proceso.',10],
    ['data','Datos territoriales','Disponibilidad de PDOT/PUGS, cartografía y estudios previos.',10],
    ['payment','Riesgo de cobro','5 = bajo riesgo de cobro; 1 = alto riesgo.',7],
    ['delivery','Viabilidad técnica/logística','5 = ejecución simple; 1 = alta incertidumbre/costo.',8],
    ['advantage','Ventaja competitiva','Diferenciación técnica, antecedentes y relación.',5]
  ];
  const weights=criteria.reduce((a,x)=>a+x[3],0);
  const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
  const fmtArea=v=>v===null||v===''?'Pendiente':new Intl.NumberFormat('es-EC',{maximumFractionDigits:2}).format(Number(v))+' ha';
  function loadEvals(){try{return JSON.parse(localStorage.getItem(STORAGE)||'{}')}catch{return{}}}
  let evals=loadEvals();
  function saveEvals(){localStorage.setItem(STORAGE,JSON.stringify(evals))}
  function scoreOf(e){if(!e?.ratings)return null;let total=0,filled=0;criteria.forEach(([id,,,w])=>{const v=Number(e.ratings[id]);if(v>=1&&v<=5){total+=(v/5)*w;filled++}});return filled===criteria.length?Math.round(total):null}
  function category(score,blocked=false){if(blocked)return 'X · NO-GO';if(score===null)return 'Sin calificar';if(score>=80)return 'A · Estratégico';if(score>=65)return 'B · Prioritario';if(score>=50)return 'C · Desarrollar';if(score>=35)return 'D · Monitorear';return 'X · NO-GO provisional'}
  function riskLabel(e){if(!e?.ratings)return 'Sin evaluar';const vals=['payment','delivery','data'].map(k=>Number(e.ratings[k])).filter(x=>x>=1&&x<=5);if(vals.length<3)return 'Sin evaluar';const avg=vals.reduce((a,b)=>a+b,0)/vals.length;return avg>=4?'Bajo':avg>=3?'Medio':'Alto'}
  function evalFor(r){const e=evals[r.dpa]||null;return{raw:e,score:scoreOf(e),category:category(scoreOf(e),!!e?.blocked),risk:riskLabel(e)}}
  function marketStats(){const st=MARKET.stats(),vals=MARKET.records.map(evalFor);return{...st,qualified:vals.filter(x=>x.score!==null).length,A:vals.filter(x=>x.category.startsWith('A')).length,B:vals.filter(x=>x.category.startsWith('B')).length,blocked:vals.filter(x=>x.category.startsWith('X')).length}}
  function businessKpis(){const st=marketStats();$('kpis').innerHTML=[['Mercado cantonal',st.cantons,'GAD municipales registrados'],['Provincias',st.provinces,'cobertura nacional'],['PDOT/PUGS urbano validado',st.withUrban,`${st.pendingUrban} pendientes de completar`],['Clientes precalificados',st.qualified,`${st.A} A · ${st.B} B`],['NO-GO / bloqueo',st.blocked,'requieren decisión gerencial']].map(([a,b,c])=>`<article class="kpi card"><small>${a}</small><strong>${b}</strong><small>${c}</small></article>`).join('')}
  function marketRows(){const province=$('marketProvince')?.value||'Todas',cat=$('marketCategory')?.value||'Todas',status=$('marketTerritoryStatus')?.value||'Todas',q=($('marketSearch')?.value||'').trim().toLowerCase();return MARKET.records.filter(r=>{const e=evalFor(r),territory=r.urbanOfficialHa!==null?'Con área urbana oficial':'PDOT/PUGS pendiente';return(province==='Todas'||r.province===province)&&(cat==='Todas'||e.category===cat)&&(status==='Todas'||territory===status)&&(!q||(r.dpa+' '+r.province+' '+r.canton+' '+r.gad).toLowerCase().includes(q))})}
  function renderMarketTable(){const host=$('marketTable');if(!host)return;const rows=marketRows();$('marketCount').textContent=`${rows.length} de ${MARKET.records.length} GAD`;host.innerHTML=rows.map(r=>{const e=evalFor(r),verified=r.urbanOfficialHa!==null;return`<tr><td><strong>${esc(r.dpa)}</strong></td><td>${esc(r.province)}</td><td><strong>${esc(r.canton)}</strong><small style="display:block;color:var(--muted)">${esc(r.gad)}</small></td><td>${fmtArea(r.urbanOfficialHa)}</td><td>${fmtArea(r.expansionOfficialHa)}</td><td><span class="status ${verified?'ok':'warn'}">${verified?'Base parcial validada':'PDOT/PUGS pendiente'}</span></td><td><span class="status ${e.category.startsWith('A')?'ok':e.category.startsWith('X')?'bad':'warn'}">${esc(e.category)}</span>${e.score!==null?`<small style="display:block;color:var(--muted)">${e.score}/100</small>`:''}</td><td><span class="status ${e.risk==='Bajo'?'ok':e.risk==='Alto'?'bad':'warn'}">${esc(e.risk)}</span></td><td>${esc(e.raw?.nextAction||r.nextAction)}</td><td><button class="btn" data-market-eval="${esc(r.dpa)}">Evaluar</button></td></tr>`}).join('');host.querySelectorAll('[data-market-eval]').forEach(b=>b.onclick=()=>openEvaluation(b.dataset.marketEval))}
  function businessHome(){const provinces=['Todas',...MARKET.provinces],cats=['Todas','A · Estratégico','B · Prioritario','C · Desarrollar','D · Monitorear','X · NO-GO','X · NO-GO provisional','Sin calificar'];return`<div class="panel-head"><div><div class="panel-title">Radar de negocios · Mercado nacional</div><div class="panel-sub">222 GAD cantonales → precalificación → oportunidad → propuesta. El proyecto se crea después de superar el GO/NO-GO.</div></div><div class="panel-actions"><button class="btn" id="showCriteria">Criterios GO/NO-GO</button><button class="btn primary" id="marketNewProject">＋ Convertir oportunidad</button></div></div><div class="metrics"><div class="metric"><small>Universo objetivo</small><strong>222 GAD</strong><span class="muted">Catálogo DPA nacional</span></div><div class="metric"><small>Dato territorial base</small><strong>${MARKET.stats().withUrban}</strong><span class="muted">área urbana PDOT/PUGS validada</span></div><div class="metric"><small>Criterios de decisión</small><strong>${criteria.length}</strong><span class="muted">ponderación total ${weights}%</span></div><div class="metric"><small>Regla comercial</small><strong>GO / NO-GO</strong><span class="muted">antes de invertir en oferta</span></div></div><div class="detail"><div class="box"><h3>Qué revisar antes de iniciar un proceso</h3>${criteria.map(([id,label,desc,w])=>`<div class="listrow"><div><strong>${esc(label)}</strong><small>${esc(desc)}</small></div><span class="badge">${w}%</span></div>`).join('')}</div><div class="box"><h3>Categorías de interés</h3>${[['A · Estratégico','80–100','Prioridad de prospección y preparación.'],['B · Prioritario','65–79','Desarrollar contacto y validar presupuesto/ventana.'],['C · Desarrollar','50–64','Madurar necesidad, datos y relación.'],['D · Monitorear','35–49','Seguimiento periódico sin alto gasto comercial.'],['X · NO-GO','<35 / bloqueo','No invertir en proceso hasta que cambie la condición.']].map(x=>`<div class="listrow"><div><strong>${x[0]}</strong><small>${x[2]}</small></div><span class="badge">${x[1]}</span></div>`).join('')}<div class="callout warn" style="margin-top:9px"><strong>Bloqueos especiales.</strong><div class="muted">TDR técnicamente inviables, ausencia de competencia legal, riesgo de cobro inaceptable, plazo imposible, conflicto de interés o costo de preparar la oferta desproporcionado pueden producir NO-GO aunque el puntaje sea alto.</div></div></div></div><div class="box" style="margin-top:12px"><div class="row"><div><h3 style="margin:0">Cartera potencial de GAD cantonales</h3><small id="marketCount" class="muted"></small></div><span class="badge">PDOT/PUGS como base territorial</span></div><div class="filters" style="box-shadow:none;margin:10px 0 0;padding:0;border:0"><label class="field search"><span>Buscar GAD / cantón / DPA</span><input id="marketSearch" placeholder="Ej. Loja, Guayaquil, 1101"></label><label class="field"><span>Provincia</span><select id="marketProvince">${provinces.map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label class="field"><span>Categoría</span><select id="marketCategory">${cats.map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label class="field"><span>Territorio</span><select id="marketTerritoryStatus"><option>Todas</option><option>Con área urbana oficial</option><option>PDOT/PUGS pendiente</option></select></label></div><div class="table-wrap" style="max-height:560px;margin-top:10px"><table class="table"><thead><tr><th>DPA</th><th>Provincia</th><th>Cliente potencial</th><th>Área urbana</th><th>Expansión</th><th>Base territorial</th><th>Interés</th><th>Riesgo</th><th>Próxima acción</th><th></th></tr></thead><tbody id="marketTable"></tbody></table></div></div>`}
  function installBusinessHandlers(){['marketSearch','marketProvince','marketCategory','marketTerritoryStatus'].forEach(id=>{const el=$(id);if(el)el.oninput=el.onchange=renderMarketTable});const c=$('showCriteria');if(c)c.onclick=()=>{document.querySelector('.detail')?.scrollIntoView({behavior:'smooth',block:'start'})};const n=$('marketNewProject');if(n)n.onclick=()=>$('newBtn').click();renderMarketTable()}
  function ensureEvalModal(){if($('marketEvalModal'))return;document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="marketEvalModal"><div class="back" data-market-close></div><section class="modal-card"><div class="modal-head"><div><strong id="marketEvalTitle">Precalificación comercial</strong><div class="muted" id="marketEvalSub"></div></div><button class="btn" data-market-close>✕</button></div><div class="modal-body" id="marketEvalBody"></div><div class="modal-foot"><button class="btn" data-market-close>Cancelar</button><button class="btn primary" id="marketEvalSave">Guardar valoración</button></div></section></div>`);document.querySelectorAll('[data-market-close]').forEach(x=>x.onclick=()=>$('marketEvalModal').classList.remove('open'))}
  let activeDpa=null;
  function openEvaluation(dpa){ensureEvalModal();activeDpa=dpa;const r=MARKET.records.find(x=>x.dpa===dpa),e=evals[dpa]||{ratings:{},blocked:false,nextAction:r.nextAction,notes:''};$('marketEvalTitle').textContent=`${r.dpa} · ${r.canton}`;$('marketEvalSub').textContent=`${r.province} · ${r.gad}`;$('marketEvalBody').innerHTML=`<div class="callout"><strong>Base territorial</strong><div class="muted">Área urbana: ${fmtArea(r.urbanOfficialHa)} · Expansión: ${fmtArea(r.expansionOfficialHa)} · ${r.sourceStatus==='pendiente_pdout_pugs'?'PDOT/PUGS pendiente de validar':esc(r.sourceLabel)}</div></div><div style="margin-top:12px">${criteria.map(([id,label,desc,w])=>`<div class="listrow"><div style="max-width:70%"><strong>${esc(label)}</strong><small>${esc(desc)} · Peso ${w}%</small></div><select class="field" style="min-width:130px" data-rating="${id}"><option value="">Sin evaluar</option>${[1,2,3,4,5].map(v=>`<option value="${v}" ${Number(e.ratings?.[id])===v?'selected':''}>${v} / 5</option>`).join('')}</select></div>`).join('')}</div><label class="field" style="margin-top:12px"><span>Próxima acción comercial</span><input id="evalNext" value="${esc(e.nextAction||'')}"></label><label class="field" style="margin-top:10px"><span>Consideraciones especiales</span><input id="evalNotes" value="${esc(e.notes||r.specialNotes||'')}" placeholder="Restricciones, actores, TDR, financiamiento, competencia..."></label><label class="listrow" style="margin-top:8px"><span><strong>Bloqueo / NO-GO gerencial</strong><small>Marcar si existe una condición que impide participar aunque el puntaje sea favorable.</small></span><input id="evalBlocked" type="checkbox" ${e.blocked?'checked':''} style="width:auto"></label>`;$('marketEvalSave').onclick=saveEvaluation;$('marketEvalModal').classList.add('open')}
  function saveEvaluation(){const ratings={};document.querySelectorAll('#marketEvalBody [data-rating]').forEach(x=>ratings[x.dataset.rating]=x.value);evals[activeDpa]={ratings,blocked:$('evalBlocked').checked,nextAction:$('evalNext').value,notes:$('evalNotes').value,updatedAt:new Date().toISOString()};saveEvals();$('marketEvalModal').classList.remove('open');businessKpis();renderMarketTable()}

  const oldRenderKpis=renderKpis,oldRenderProjects=renderProjects,oldRenderMain=renderMain;
  renderKpis=function(){if(s.section==='negocios')businessKpis();else oldRenderKpis()};
  renderProjects=function(){if(s.section==='negocios'){$('projects').innerHTML='';$('projects').classList.add('hidden')}else{$('projects').classList.remove('hidden');oldRenderProjects()}};
  renderMain=function(){if(s.section==='negocios'){$('main').innerHTML=businessHome();installBusinessHandlers()}else oldRenderMain()};
  renderNav=function(){const items=[['negocios','◎','Negocios / Mercado'],['panel','▦','Proyectos'],['acciones','✓','Mis acciones'],['control','◆','Control / Gates'],['operacion','⚙','Operación técnica'],['direccion','◉','Dirección'],['documentos','▤','Documentos'],['alertas','⚠','Alertas']];$('nav').innerHTML=items.map(x=>`<button class="navbtn ${s.section===x[0]?'active':''}" data-sec="${x[0]}"><span>${x[1]} ${x[2]}</span><span>${x[0]==='negocios'?MARKET.records.length:x[0]==='alertas'?project().alerts.length:'›'}</span></button>`).join('');document.querySelectorAll('[data-sec]').forEach(b=>b.onclick=()=>{s.section=b.dataset.sec;renderAll()})};

  const draft=window.SmartRiskConsultoriaDraft||(window.SmartRiskConsultoriaDraft={gad:'',contact:'',email:'',phone:'',province:'',canton:'',officialUrbanHa:'',officialExpansionHa:'',projectUrbanHa:'',projectExpansionHa:'',service:'Microzonificación sísmica integral',complexity:'Media',months:4,technicians:4});
  function captureDraft(){const ids={newGad:'gad',newContact:'contact',newEmail:'email',newPhone:'phone',newProvince:'province',newCanton:'canton',projectUrbanHa:'projectUrbanHa',projectExpansionHa:'projectExpansionHa',newService:'service',newComplexity:'complexity',newMonths:'months',newTechnicians:'technicians'};Object.entries(ids).forEach(([id,k])=>{const el=$(id);if(el)draft[k]=el.value})}
  function official(){return MARKET.get(draft.province,draft.canton)}
  function applyOfficial(){const r=official(),u=r?.urbanOfficialHa??'',e=r?.expansionOfficialHa??'';draft.officialUrbanHa=u;draft.officialExpansionHa=e;if(draft.projectUrbanHa===''||draft._lastAutoUrban===draft.projectUrbanHa){draft.projectUrbanHa=u;draft._lastAutoUrban=u}if(draft.projectExpansionHa===''||draft._lastAutoExpansion===draft.projectExpansionHa){draft.projectExpansionHa=e;draft._lastAutoExpansion=e}}
  wizard=function(){captureDraft();const labels=['Cliente','Territorio','Servicio','Presupuesto'];$('steps').innerHTML=labels.map((x,i)=>`<div class="step ${i===s.wizard?'active':''}">${i+1}. ${x}</div>`).join('');let html='';if(s.wizard===0)html=`<div class="formgrid"><label class="field"><span>Entidad / GAD</span><input id="newGad" value="${esc(draft.gad)}" placeholder="GAD Municipal de..."></label><label class="field"><span>Contacto principal</span><input id="newContact" value="${esc(draft.contact)}" placeholder="Nombre y cargo"></label><label class="field"><span>Correo</span><input id="newEmail" value="${esc(draft.email)}" type="email"></label><label class="field"><span>Teléfono</span><input id="newPhone" value="${esc(draft.phone)}"></label></div>`;else if(s.wizard===1){applyOfficial();const cantons=MARKET.byProvince[draft.province]||[],r=official();html=`<div class="formgrid"><label class="field"><span>Provincia</span><select id="newProvince"><option value="">Seleccione provincia</option>${MARKET.provinces.map(v=>`<option ${draft.province===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label><label class="field"><span>Cantón</span><select id="newCanton"><option value="">Seleccione cantón</option>${cantons.map(v=>`<option ${draft.canton===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label><label class="field"><span>Área urbana oficial PDOT/PUGS</span><input value="${esc(draft.officialUrbanHa)}" readonly placeholder="Pendiente de validación"></label><label class="field"><span>Expansión oficial PDOT/PUGS</span><input value="${esc(draft.officialExpansionHa)}" readonly placeholder="Pendiente de validación"></label><label class="field"><span>Área urbana utilizada en este proyecto (ha)</span><input id="projectUrbanHa" value="${esc(draft.projectUrbanHa)}" type="number" min="0" step="0.01"></label><label class="field"><span>Expansión / área adicional utilizada (ha)</span><input id="projectExpansionHa" value="${esc(draft.projectExpansionHa)}" type="number" min="0" step="0.01"></label></div><div class="callout ${r?.urbanOfficialHa!==null&&r?'ok':'warn'}" style="margin-top:10px"><strong>${r?.urbanOfficialHa!==null&&r?'Base PDOT/PUGS disponible':'Dato oficial pendiente de validación'}</strong><div class="muted">${r?.sourceLabel?esc(r.sourceLabel+' · '+r.sourceDate):'El cantón existe en el registro nacional, pero la superficie no se inventa: queda pendiente hasta cargar el instrumento oficial.'}</div></div><div class="callout" style="margin-top:10px"><strong>Regla de trazabilidad.</strong><div class="muted">El dato oficial se conserva. Si el cliente/TDR define un polígono distinto, se modifica solo el área del proyecto y queda registrado como ajuste técnico.</div></div>`}else if(s.wizard===2)html=`<div class="formgrid"><label class="field"><span>Servicio</span><select id="newService">${['Microzonificación sísmica integral','Estudio técnico base','Campaña geotécnica-geofísica'].map(v=>`<option ${draft.service===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field"><span>Complejidad</span><select id="newComplexity">${['Baja','Media','Alta'].map(v=>`<option ${draft.complexity===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field"><span>Plazo (meses)</span><input id="newMonths" value="${esc(draft.months)}" type="number" min="1"></label><label class="field"><span>Técnicos</span><input id="newTechnicians" value="${esc(draft.technicians)}" type="number" min="1"></label></div>`;else{const total=(Number(draft.projectUrbanHa)||0)+(Number(draft.projectExpansionHa)||0);html=`<div class="callout"><strong>Base territorial de estimación</strong><div class="muted">${esc(draft.province||'Provincia pendiente')} · ${esc(draft.canton||'Cantón pendiente')} · Área objetivo ${fmtArea(total)}</div></div><div class="metrics"><div class="metric"><small>Área urbana oficial</small><strong>${fmtArea(draft.officialUrbanHa)}</strong></div><div class="metric"><small>Área de proyecto</small><strong>${fmtArea(total)}</strong></div><div class="metric"><small>Plazo</small><strong>${esc(draft.months)} meses</strong></div><div class="metric"><small>Origen</small><strong>${official()?.urbanOfficialHa!==null?'PDOT/PUGS + ajuste':'Ajuste provisional'}</strong></div></div>`}$('wizardBody').innerHTML=html;$('backBtn').disabled=s.wizard===0;$('nextBtn').textContent=s.wizard===3?'Crear borrador':'Continuar'};
  document.addEventListener('change',e=>{if(e.target.id==='newProvince'){draft.province=e.target.value;draft.canton='';draft.projectUrbanHa='';draft.projectExpansionHa='';draft._lastAutoUrban='';draft._lastAutoExpansion='';wizard()}if(e.target.id==='newCanton'){draft.canton=e.target.value;draft.projectUrbanHa='';draft.projectExpansionHa='';draft._lastAutoUrban='';draft._lastAutoExpansion='';applyOfficial();wizard()}});

  s.section='negocios';renderAll();
  window.SmartRiskBusinessMarket={criteria,evalFor,scoreOf,category,marketStats,openEvaluation};
})();